ffi_fn ! { # [doc = " Creates a task that will poll a response body for the next buffer of data."] # [doc = ""] # [doc = " The task may have different types depending on the outcome:"] # [doc = ""] # [doc = " - `HYPER_TASK_BUF`: Success, and more data was received."] # [doc = " - `HYPER_TASK_ERROR`: An error retrieving the data."] # [doc = " - `HYPER_TASK_EMPTY`: The body has finished streaming data."] # [doc = ""] # [doc = " When the application receives the task from `hyper_executor_poll`,"] # [doc = " if the task type is `HYPER_TASK_BUF`, it should cast the task to"] # [doc = " `hyper_buf *` and consume all the bytes in the buffer. Then"] # [doc = " the application should call `hyper_body_data` again for the same"] # [doc = " `hyper_body *`, to create a task for the next buffer of data."] # [doc = " Repeat until the polled task type is `HYPER_TASK_ERROR` or"] # [doc = " `HYPER_TASK_EMPTY`."] # [doc = ""] # [doc = " To avoid a memory leak, the task must eventually be consumed by"] # [doc = " `hyper_task_free`, or taken ownership of by `hyper_executor_push`"] # [doc = " without subsequently being given back by `hyper_executor_poll`."] # [doc = ""] # [doc = " This does not consume the `hyper_body *`, so it may be used again."] # [doc = " However, the `hyper_body *` MUST NOT be used or freed until the"] # [doc = " related task is returned from `hyper_executor_poll`."] # [doc = ""] # [doc = " For a more convenient method, see also `hyper_body_foreach`."] fn hyper_body_data (body : * mut hyper_body) -> * mut hyper_task { let mut body = ManuallyDrop :: new (non_null ! (Box :: from_raw (body) ?= ptr :: null_mut ())) ; Box :: into_raw (hyper_task :: boxed (async move { loop { match body . 0 . frame () . await { Some (Ok (frame)) => { if let Ok (data) = frame . into_data () { return Ok (Some (hyper_buf (data))) ; } else { continue ; } } , Some (Err (e)) => return Err (e) , None => return Ok (None) , } } })) } ?= ptr :: null_mut () }